CREATE OR REPLACE FUNCTION public.bump_product_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin new.revision:=old.revision+1;return new;end$function$;

CREATE OR REPLACE FUNCTION public.store_add_workspace_admin(p_email text, p_name text)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$ select store_private.add_workspace_admin(p_email,p_name); $function$;

CREATE OR REPLACE FUNCTION store_private.enforce_own_admin_mfa()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not store_private.admin_session_active() or (auth.jwt()->>'aal') is distinct from 'aal2'
 or not exists(select 1 from public.store_admins where user_id=auth.uid())
 or not exists(select 1 from auth.mfa_factors where user_id=auth.uid() and status='verified') then
  raise exception 'Verified administrator MFA required' using errcode='42501';
 end if;
 insert into store_private.admin_mfa_enforcement(user_id) values(auth.uid()) on conflict do nothing;
 delete from store_private.admin_mfa_pauses where user_id=auth.uid();
 return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_store_mfa()
 RETURNS boolean
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  SELECT store_private.enforce_own_admin_mfa();
$function$;

CREATE OR REPLACE FUNCTION public.store_remove_workspace_admin(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$ select store_private.remove_workspace_admin(p_user_id); $function$;

