 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$ select store_private.finance_history(p_id); $function$;

CREATE OR REPLACE FUNCTION store_private.finance_history(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 perform store_private.require_workspace_admin(true);
 select coalesce(jsonb_agg(to_jsonb(c) order by id::bigint desc),'[]'::jsonb) into result from (
  select id::text,changed_at,actor_label,before_data,after_data from store_private.finance_changes c0 where entity='finance_entries' and record_id=p_id::text order by c0.id desc limit 20
 ) c;return result;
end $function$;

CREATE OR REPLACE FUNCTION store_private.valid_product_image(value text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
 select value ~ '^https://(juliproz-store[.]vercel[.]app/images/|qhgzzhgxwpcctafpzjid[.]supabase[.]co/storage/v1/object/public/product-photos/)[A-Za-z0-9._/-]+$' and value !~ '/[.][.](/|$)';
$function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION store_private.admin_mfa_satisfied()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select store_private.admin_session_active() and auth.uid() is not null and
 ((auth.jwt()->>'aal')='aal2' or exists(
  select 1 from store_private.admin_mfa_pauses p join public.store_admins a on a.user_id=p.user_id where p.user_id=auth.uid()
 ));
$function$;

CREATE OR REPLACE FUNCTION public.store_analytics_summary(p_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result jsonb; since timestamptz;
begin
 if not store_private.admin_mfa_satisfied() or not exists(select 1 from public.store_admins where user_id=auth.uid()) then raise exception 'admin required' using errcode='42501';end if;
 since=now()-make_interval(days=>greatest(1,least(30,coalesce(p_days,7))));
 select coalesce(jsonb_object_agg(event,n),'{}'::jsonb) into result from(select event,count(*) n from store_private.analytics_events where created_at>=since group by event)t;
 result=result||jsonb_build_object(
 'active',(select count(distinct visitor_id) from store_private.analytics_sessions where last_seen>=now()-interval '2 minutes'),
 'visitors',(select count(distinct visitor_id) from store_private.analytics_sessions where last_seen>=since),
 'sessions',(select count(*) from store_private.analytics_sessions where started_at>=since),
 'event_visitors',coalesce((select jsonb_object_agg(event,n) from(select event,count(distinct visitor_id) n from store_private.analytics_events where created_at>=since group by event)t),'{}'::jsonb),
 'daily',coalesce((select jsonb_agg(to_jsonb(t) order by "day") from(
 select (created_at at time zone 'Asia/Bangkok')::date as "day",count(distinct visitor_id) visitors,
 count(*) filter(where event='product_view') views,
 count(*) filter(where event='cart_add') cart,
 count(*) filter(where event='checkout_open' or event like 'manager_%') contacts
 from store_private.analytics_events where created_at>=since group by 1)t),'[]'::jsonb),
 'products',coalesce((select jsonb_agg(to_jsonb(t)) from(
 select p.id,p.brand,p.name,count(*) filter(where e.event='product_view') views,
 count(*) filter(where e.event='wishlist_add') wishlist,count(*) filter(where e.event='cart_add') cart,
 count(*) filter(where e.event='manager_product') contacts,
 count(*) filter(where e.event='manager_search_product') search_contacts
 from store_private.analytics_events e join public.products p on p.id=e.product_id where e.created_at>=since
 group by p.id,p.brand,p.name order by count(*) filter(where e.event='product_view') desc,p.id limit 20)t),'[]'::jsonb));
 return result;
end; $function$;

CREATE OR REPLACE FUNCTION public.store_product_wishlist_counts(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare days integer=greatest(1,least(30,coalesce(p_days,30)));counts jsonb;
begin
 if not store_private.admin_mfa_satisfied() or not exists(select 1 from public.store_admins where user_id=auth.uid()) then raise exception 'admin required' using errcode='42501';end if;
 select coalesce(jsonb_object_agg(product_id::text,n),'{}'::jsonb) into counts from(select product_id,count(*) n from store_private.analytics_events where event='wishlist_add' and product_id is not null and created_at>=now()-make_interval(days=>days) group by product_id)t;
 return jsonb_build_object('days',days,'counts',counts);
end;$function$;

CREATE OR REPLACE FUNCTION store_private.own_admin_security_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare own_role text;
begin
 if not store_private.admin_session_active() then raise exception 'Active session required' using errcode='42501';end if;
 select access_role into own_role from public.store_admins where user_id=auth.uid();
 if own_role is not null then return jsonb_build_object('paused',exists(select 1 from store_private.admin_mfa_pauses where user_id=auth.uid()),'pending',false,'access_role',own_role);end if;
 if exists(select 1 from auth.users u join store_private.admin_invitations i on lower(i.email)=lower(u.email) where u.id=auth.uid() and u.email_confirmed_at is not null and i.expires_at>now()) then
 return jsonb_build_object('paused',false,'pending',true,'access_role',null);end if;
 raise exception 'Administrator or current invitation required' using errcode='42501';
end; $function$;

CREATE OR REPLACE FUNCTION public.store_admin_security_status()
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$select store_private.own_admin_security_status();$function$;

CREATE OR REPLACE FUNCTION store_private.valid_product_photos(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare photo jsonb;
begin
 if jsonb_typeof(value)<>'array' or jsonb_array_length(value)>20 then return false;end if;
 for photo in select * from jsonb_array_elements(value) loop
  if jsonb_typeof(photo)<>'string' or length(photo #>> '{}')>2048 or not coalesce(store_private.valid_product_image(photo #>> '{}'),false) then return false;end if;
 end loop;
 return true;
end;$function$;

CREATE OR REPLACE FUNCTION public.store_analytics_daily_salt()
 RETURNS text
 LANGUAGE sql
 SET search_path TO ''
AS $function$
 select encode(extensions.hmac(convert_to(current_date::text,'UTF8'),seed,'sha256'),'hex') from store_private.analytics_secret where singleton;
$function$;

CREATE OR REPLACE FUNCTION public.store_analytics_health()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$select store_private.own_analytics_health();$function$;

CREATE OR REPLACE FUNCTION store_private.own_analytics_health()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform store_private.require_workspace_admin();
 return exists(select 1 from store_private.analytics_limits where
 (key='global:minute' and window_at=date_trunc('minute',now()) and hits>=1920) or
 (key='global:day:'||current_date::text and window_at=date_trunc('day',now()) and hits>=200000) or
 (key like 'ip:day:'||current_date::text||':%' and window_at=date_trunc('day',now()) and hits>=16000) or
 (key='sessions:global' and window_at=date_trunc('minute',now()) and hits>=240));
end; $function$;

CREATE OR REPLACE FUNCTION store_private.log_store_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); before_data jsonb; after_data jsonb; label text;
begin
 if tg_table_schema<>'public' or tg_table_name not in ('products','store_admins','product_admin_notes') or tg_when<>'AFTER' then raise exception 'Unexpected audit trigger target'; end if;
 if actor is null and current_setting('role',true)='authenticated' then raise exception 'Authenticated actor is required' using errcode='42501'; end if;
 if tg_op<>'INSERT' then before_data:=to_jsonb(old); end if;
 if tg_op<>'DELETE' then after_data:=to_jsonb(new); end if;
 if tg_op='UPDATE' and (before_data-'revision')=(after_data-'revision') then return new; end if;
 if actor is not null then
  select coalesce(nullif(a.display_name,''),u.email,actor::text) into label from auth.users u left join public.store_admins a on a.user_id=u.id where u.id=actor;
 end if;
 insert into store_private.store_change_log(actor_id,actor_label,actor_role,entity,operation,record_id,before_row,after_row)
 values(actor,coalesce(label,case when actor is null then 'Системное изменение' else actor::text end),coalesce(auth.jwt()->>'role',session_user::text),tg_table_name,tg_op,
 coalesce(after_data->>'id',before_data->>'id',after_data->>'user_id',before_data->>'user_id',after_data->>'product_id',before_data->>'product_id'),before_data,after_data);
 if tg_op='DELETE' then return old; end if; return new;
end $function$;

CREATE OR REPLACE FUNCTION store_private.require_workspace_admin(owner_only boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null or not exists(select 1 from public.store_admins where user_id=auth.uid() and (not owner_only or access_role='owner')) or not store_private.admin_mfa_satisfied() then
  raise exception 'Доступ только для администраторов магазина' using errcode='42501';
 end if;
 if owner_only and (auth.jwt()->>'aal') is distinct from 'aal2' then raise exception 'Для управления доступами подтвердите двухфакторную защиту в настройках' using errcode='42501'; end if;
end $function$;

CREATE OR REPLACE FUNCTION store_private.save_workspace_profile(p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform store_private.require_workspace_admin();
 if p_name is null or char_length(btrim(p_name)) not between 1 and 100 then raise exception 'Имя должно содержать от 1 до 100 символов'; end if;
 update public.store_admins set display_name=btrim(p_name) where user_id=auth.uid();
 return store_private.workspace_team();
end $function$;

CREATE OR REPLACE FUNCTION store_private.workspace_team()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; pending jsonb:='[]'::jsonb;
begin
 perform store_private.require_workspace_admin();
 select jsonb_build_object('current_user_id',auth.uid(),'members',coalesce(jsonb_agg(jsonb_build_object('user_id',a.user_id,'display_name',a.display_name,'email',u.email,'access_role',a.access_role) order by a.access_role desc,a.display_name,u.email),'[]'::jsonb)) into result from public.store_admins a join auth.users u on u.id=a.user_id;
 if exists(select 1 from public.store_admins where user_id=auth.uid() and access_role='owner') then
  select coalesce(jsonb_agg(jsonb_build_object(
   'email',i.email,'display_name',i.display_name,
   'email_confirmed',u.email_confirmed_at is not null,
   'mfa_confirmed',exists(select 1 from auth.mfa_factors f where f.user_id=u.id and f.status='verified' and f.factor_type='totp'),
   'ready',u.email_confirmed_at is not null and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now()) and exists(select 1 from auth.mfa_factors f where f.user_id=u.id and f.status='verified' and f.factor_type='totp')
  ) order by i.created_at),'[]'::jsonb)
  into pending from store_private.admin_invitations i left join auth.users u on lower(u.email)=lower(i.email)
  where i.expires_at>now() and not exists(select 1 from public.store_admins a where a.user_id=u.id);
 end if;
 return result||jsonb_build_object('pending_invitations',pending);
end; $function$;

CREATE OR REPLACE FUNCTION store_private.remove_workspace_admin(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform store_private.require_workspace_admin(true);
 if p_user_id=auth.uid() or exists(select 1 from public.store_admins where user_id=p_user_id and access_role='owner') then raise exception 'Доступ владельца нельзя отключить здесь'; end if;
 delete from public.store_admins where user_id=p_user_id and access_role='admin';
 -- Membership checks deny the revoked user even with an unexpired access token.
 return store_private.workspace_team();
end $function$;

CREATE OR REPLACE FUNCTION store_private.workspace_history(p_before bigint DEFAULT NULL::bigint, p_product_id bigint DEFAULT NULL::bigint, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 perform store_private.require_workspace_admin();
 select coalesce(jsonb_agg(row_data order by id desc),'[]'::jsonb) into result from (
 select l.id,jsonb_build_object('id',l.id::text,'changed_at',l.changed_at,'actor_id',l.actor_id,
 'actor_label',coalesce(l.actor_label,nullif(a.display_name,''),u.email,case when l.actor_id is null then 'Системное изменение' else l.actor_id::text end),
 'entity',l.entity,'operation',l.operation,'record_id',l.record_id,
 'product_label',case when l.entity='products' then concat_ws(' ',coalesce(l.after_row->>'brand',l.before_row->>'brand'),coalesce(l.after_row->>'name',l.before_row->>'name')) when l.entity='product_admin_notes' then (select concat_ws(' ',p.brand,p.name) from public.products p where p.id::text=l.record_id) else null end,
 'changes',(select coalesce(jsonb_object_agg(k,jsonb_build_object('before',l.before_row->k,'after',l.after_row->k)),'{}'::jsonb)
 from (select jsonb_object_keys(coalesce(l.before_row,'{}'::jsonb)) k union select jsonb_object_keys(coalesce(l.after_row,'{}'::jsonb))) keys
 where k not in ('revision','creation_key','created_at','id','product_id','user_id') and (l.before_row->k) is distinct from (l.after_row->k))) row_data
 from store_private.store_change_log l left join public.store_admins a on a.user_id=l.actor_id left join auth.users u on u.id=l.actor_id
 where (p_before is null or l.id<p_before) and (p_actor_id is null or l.actor_id=p_actor_id)
 and (p_product_id is null or (l.entity in ('products','product_admin_notes') and l.record_id=p_product_id::text))
 order by l.id desc limit 31) records;
 return result;
end $function$;

