CREATE OR REPLACE FUNCTION public.touch_store_admin_session()
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$SELECT store_private.touch_own_admin_session();$function$;

CREATE OR REPLACE FUNCTION store_private.touch_own_admin_session()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '2s'
AS $function$
DECLARE s auth.sessions%ROWTYPE; t timestamptz; deadline timestamptz;
BEGIN
 -- Lock the actual caller's session; do not accept a client-selected session ID or time.
 SELECT ss.* INTO s FROM auth.sessions ss JOIN auth.users u ON u.id=ss.user_id
 WHERE ss.id::text=auth.jwt()->>'session_id' AND ss.user_id=auth.uid()
 AND u.deleted_at IS NULL AND (u.banned_until IS NULL OR u.banned_until<=now())
 FOR UPDATE OF ss;
 t:=clock_timestamp();
 IF s.id IS NULL OR s.created_at IS NULL THEN RAISE EXCEPTION 'Active session required' USING ERRCODE='42501';END IF;
 deadline:=least(s.created_at+interval '30 days',s.not_after);
 IF deadline<=t THEN
  RAISE EXCEPTION 'Session expired; sign in again' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.store_admins WHERE user_id=s.user_id)
 AND NOT EXISTS(SELECT 1 FROM auth.users u JOIN store_private.admin_invitations i ON lower(i.email)=lower(u.email)
  WHERE u.id=s.user_id AND u.email_confirmed_at IS NOT NULL AND i.expires_at>t) THEN
  RAISE EXCEPTION 'Administrator or current invitation required' USING ERRCODE='42501';
 END IF;
 INSERT INTO store_private.admin_session_activity(session_id,last_seen) VALUES(s.id,t)
 ON CONFLICT(session_id) DO UPDATE SET last_seen=greatest(admin_session_activity.last_seen,excluded.last_seen);
 RETURN jsonb_build_object('server_now',t,'expires_at',deadline,'idle_expires_at',deadline);
END; $function$;

CREATE OR REPLACE FUNCTION store_private.purge_analytics_history()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET lock_timeout TO '2s'
AS $function$
DECLARE n bigint; e bigint:=0; s bigint:=0; l bigint:=0; cutoff timestamptz:=now()-interval '90 days';
BEGIN
 IF NOT pg_try_advisory_xact_lock(840120261013::bigint) THEN RETURN jsonb_build_object('skipped',true);END IF;
 FOR i IN 1..50 LOOP
  DELETE FROM store_private.analytics_events WHERE event_id IN
   (SELECT event_id FROM store_private.analytics_events WHERE created_at<cutoff ORDER BY created_at LIMIT 10000);
  GET DIAGNOSTICS n=ROW_COUNT;e:=e+n;EXIT WHEN n<10000;
 END LOOP;
 FOR i IN 1..50 LOOP
  DELETE FROM store_private.analytics_sessions WHERE session_id IN
   (SELECT session_id FROM store_private.analytics_sessions WHERE last_seen<cutoff ORDER BY last_seen LIMIT 10000);
  GET DIAGNOSTICS n=ROW_COUNT;s:=s+n;EXIT WHEN n<10000;
 END LOOP;
 FOR i IN 1..50 LOOP
  DELETE FROM store_private.analytics_limits WHERE key IN
   (SELECT key FROM store_private.analytics_limits WHERE window_at<now()-interval '1 day' ORDER BY window_at LIMIT 10000);
  GET DIAGNOSTICS n=ROW_COUNT;l:=l+n;EXIT WHEN n<10000;
 END LOOP;
 -- Keep one month of this job's operational history, without touching other jobs.
 DELETE FROM cron.job_run_details WHERE jobid IN(SELECT jobid FROM cron.job WHERE jobname='store-analytics-retention') AND end_time<now()-interval '30 days';
 INSERT INTO store_private.analytics_retention_state VALUES(true,clock_timestamp(),e,s,l)
 ON CONFLICT(singleton) DO UPDATE SET completed_at=excluded.completed_at,events_deleted=excluded.events_deleted,sessions_deleted=excluded.sessions_deleted,limits_deleted=excluded.limits_deleted;
 RETURN jsonb_build_object('events_deleted',e,'sessions_deleted',s,'limits_deleted',l);
END; $function$;

CREATE OR REPLACE FUNCTION store_private.own_retention_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE completed timestamptz; active_job boolean; backlog boolean; failed boolean;
BEGIN
 PERFORM store_private.require_workspace_admin();
 SELECT completed_at INTO completed FROM store_private.analytics_retention_state WHERE singleton;
 SELECT active INTO active_job FROM cron.job WHERE jobname='store-analytics-retention';
 SELECT status NOT IN ('succeeded','running','starting') INTO failed FROM cron.job_run_details
  WHERE jobid IN(SELECT jobid FROM cron.job WHERE jobname='store-analytics-retention') ORDER BY runid DESC LIMIT 1;
 backlog:=EXISTS(SELECT 1 FROM store_private.analytics_events WHERE created_at<now()-interval '91 days')
  OR EXISTS(SELECT 1 FROM store_private.analytics_sessions WHERE last_seen<now()-interval '91 days');
 RETURN jsonb_build_object('healthy',coalesce(active_job,false) AND coalesce(completed>now()-interval '26 hours',false) AND NOT backlog AND NOT coalesce(failed,false),'last_completed_at',completed,'retention_days',90);
END; $function$;

CREATE OR REPLACE FUNCTION public.store_analytics_retention_health()
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$SELECT store_private.own_retention_health();$function$;

CREATE OR REPLACE FUNCTION public.store_analytics_gateway_ingest(p_secret text, p_event_id uuid, p_visitor uuid, p_session uuid, p_event text, p_product bigint, p_page text, p_fingerprint text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF p_secret IS NULL OR length(p_secret)<>64 OR NOT EXISTS(
  SELECT 1 FROM store_private.analytics_gateway_secret WHERE singleton AND secret_hash=sha256(convert_to(p_secret,'UTF8'))
 ) THEN RAISE EXCEPTION 'Unauthorized' USING ERRCODE='42501';END IF;
 RETURN public.store_analytics_ingest(p_event_id,p_visitor,p_session,p_event,p_product,p_page,p_fingerprint);
END; $function$;

CREATE OR REPLACE FUNCTION store_private.workspace_upload_schedule(p_month date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare today date:=(now() at time zone 'Europe/Kyiv')::date; first_day date; last_day date; result jsonb;
begin
 perform store_private.require_workspace_admin();
 first_day:=date_trunc('month',coalesce(p_month,today))::date;
 if first_day<date '2000-01-01' or first_day>date '2100-12-01' then raise exception 'Недопустимый месяц'; end if;
 last_day:=(first_day+interval '1 month')::date;
 with uploads as (
  select (l.changed_at at time zone 'Europe/Kyiv')::date as day,l.actor_id,
   coalesce(nullif(a.display_name,''),nullif(l.actor_label,''),case when l.actor_id is null then 'Системная загрузка' else 'Бывший сотрудник' end) as label,
   l.record_id,p.id is not null as kept
  from store_private.store_change_log l
  left join public.store_admins a on a.user_id=l.actor_id
  left join public.products p on p.id=case when l.record_id~'^[0-9]{1,18}$' then l.record_id::bigint end
  where l.entity='products' and l.operation='INSERT'
   and l.changed_at>=first_day::timestamp at time zone 'Europe/Kyiv'
   and l.changed_at<last_day::timestamp at time zone 'Europe/Kyiv'
   and not exists(select 1 from store_private.store_change_log old where old.entity='products' and old.operation='INSERT' and old.record_id=l.record_id and old.id<l.id)
 ), counts as (
  select day,actor_id,max(label) as label,count(*) filter(where kept)::integer as count,count(*) filter(where not kept)::integer as deleted_count
  from uploads group by day,actor_id
 ), days as (
  select d.*,coalesce(c.count,0) as uploaded,coalesce(c.deleted_count,0) as deleted_count,
   coalesce((select sum(x.count) from counts x where x.day=d.day and x.actor_id is distinct from d.manager_id),0) as others
  from generate_series(0,(last_day-first_day)-1) s(n)
  cross join lateral store_private.upload_duty(first_day+s.n) d
  left join counts c on c.day=d.day and c.actor_id=d.manager_id
 )
 select jsonb_build_object(
  'today',today,'month',first_day,'time_zone','Europe/Kyiv','current_user_id',auth.uid(),
  'can_manage',exists(select 1 from public.store_admins where user_id=auth.uid() and access_role='owner'),
  'days',coalesce((select jsonb_agg(to_jsonb(d) order by d.day) from days d),'[]'::jsonb),
  'counts',coalesce((select jsonb_agg(to_jsonb(c) order by c.day,c.label) from counts c),'[]'::jsonb),
  'members',coalesce((select jsonb_agg(jsonb_build_object('user_id',a.user_id,'display_name',coalesce(nullif(a.display_name,''),'Менеджер'),'access_role',a.access_role) order by a.display_name) from public.store_admins a),'[]'::jsonb),
  'rotations',coalesce((select jsonb_agg(to_jsonb(r) order by r.starts_on) from (select starts_on,manager_ids,manager_labels,revision from store_private.upload_rotations order by starts_on desc limit 100) r),'[]'::jsonb)
 ) into result;
 return result;
end $function$;

CREATE OR REPLACE FUNCTION public.store_save_upload_day(p_day date, p_manager_id uuid, p_note text, p_revision bigint, p_reset boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$ select store_private.save_upload_day(p_day,p_manager_id,p_note,p_revision,p_reset); $function$;

CREATE OR REPLACE FUNCTION public.store_analytics_gateway_ingest(p_secret text, p_event_id uuid, p_visitor uuid, p_session uuid, p_event text, p_product bigint, p_page text, p_fingerprint text, p_channel text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if p_secret is null or length(p_secret)<>64 or not exists(
  select 1 from store_private.analytics_gateway_secret where singleton and secret_hash=sha256(convert_to(p_secret,'UTF8'))
 ) then raise exception 'Unauthorized' using errcode='42501';end if;
 return public.store_analytics_ingest(p_event_id,p_visitor,p_session,p_event,p_product,p_page,p_fingerprint,p_channel);
end; $function$;

CREATE OR REPLACE FUNCTION public.store_analytics_ingest(p_event_id uuid, p_visitor uuid, p_session uuid, p_event text, p_product bigint, p_page text, p_fingerprint text, p_channel text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n integer;k text;new_session boolean;
begin
 if p_channel is null or p_channel not in ('website','telegram','legacy') then return false;end if;
 if p_event not in ('visit','heartbeat','page_view','product_view','wishlist_add','wishlist_remove','cart_add','cart_remove','checkout_open','manager_open','manager_product','manager_search_product','manager_general','manager_sell','manager_authentication','manager_atelier') or p_visitor is null or p_session is null or p_event_id is null or p_fingerprint is null or p_fingerprint !~ '^[a-f0-9]{64}$' then return false;end if;
 if p_event is null or (p_page is not null and p_page not in ('catalog','wishlist','cart')) then return false;end if;
 if p_event in ('product_view','wishlist_add','wishlist_remove','cart_add','cart_remove','manager_product','manager_search_product') and p_product is null then return false;end if;
 if p_product is not null and not exists(select 1 from public.products where id=p_product and available=true) then return false;end if;

 begin
 if exists(select 1 from store_private.analytics_events where event_id=p_event_id) then return exists(select 1 from store_private.analytics_events where event_id=p_event_id and visitor_id=p_visitor and session_id=p_session and channel=p_channel);end if;
 foreach k in array array['ip:'||p_fingerprint,'visitor:'||p_visitor::text,'global:minute','global:day:'||current_date::text,'ip:day:'||current_date::text||':'||p_fingerprint] loop
  insert into store_private.analytics_limits as l(key,window_at,hits) values(k,case when k like 'global:day:%' or k like 'ip:day:%' then date_trunc('day',now()) else date_trunc('minute',now()) end,1)
  on conflict(key) do update set window_at=excluded.window_at,hits=case when l.window_at=excluded.window_at then l.hits+1 else 1 end returning hits into n;
  if n>(case when k='global:minute' then 2400 when k like 'global:day:%' then 250000 when k like 'ip:day:%' then 20000 when k like 'ip:%' then 600 else 120 end) then raise exception using errcode='JP429',message='analytics refused';end if;
 end loop;
 new_session:=not exists(select 1 from store_private.analytics_sessions where session_id=p_session);
 if new_session then
  foreach k in array array['sessions:global','sessions:ip:'||p_fingerprint] loop
   insert into store_private.analytics_limits as l(key,window_at,hits) values(k,date_trunc('minute',now()),1)
   on conflict(key) do update set window_at=excluded.window_at,hits=case when l.window_at=excluded.window_at then l.hits+1 else 1 end returning hits into n;
   if n>(case when k='sessions:global' then 300 else 150 end) then raise exception using errcode='JP429',message='analytics refused';end if;
  end loop;
 end if;
 insert into store_private.analytics_sessions as s(session_id,visitor_id,channel) values(p_session,p_visitor,p_channel) on conflict(session_id) do update set last_seen=now() where s.visitor_id=excluded.visitor_id and s.channel=excluded.channel;
 if not found then raise exception using errcode='JP429',message='analytics refused';end if;
 if p_event<>'heartbeat' then insert into store_private.analytics_events(event_id,visitor_id,session_id,event,product_id,page,channel) values(p_event_id,p_visitor,p_session,p_event,p_product,p_page,p_channel) on conflict(event_id) do nothing;end if;
 -- Daily cron owns retention; ingestion only records the event.
 return true;
 exception when sqlstate 'JP429' then return false;
 end;
end; $function$;

CREATE OR REPLACE FUNCTION public.store_analytics_summary(p_days integer, p_channel text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result jsonb; since timestamptz;
begin
 if not store_private.admin_mfa_satisfied() or not exists(select 1 from public.store_admins where user_id=auth.uid()) then raise exception 'admin required' using errcode='42501';end if;
 if p_channel is null or p_channel not in ('website','telegram','legacy') then raise exception 'invalid analytics channel' using errcode='22023';end if;
 since=now()-make_interval(days=>greatest(1,least(30,coalesce(p_days,7))));
 select coalesce(jsonb_object_agg(event,n),'{}'::jsonb) into result from(select event,count(*) n from store_private.analytics_events where channel=p_channel and created_at>=since group by event)t;
 result=result||jsonb_build_object(
 'channel',p_channel,
 'active',(select count(distinct visitor_id) from store_private.analytics_sessions where channel=p_channel and last_seen>=now()-interval '2 minutes'),
 'visitors',(select count(distinct visitor_id) from store_private.analytics_sessions where channel=p_channel and last_seen>=since),
 'sessions',(select count(*) from store_private.analytics_sessions where channel=p_channel and started_at>=since),
 'event_visitors',coalesce((select jsonb_object_agg(event,n) from(select event,count(distinct visitor_id) n from store_private.analytics_events where channel=p_channel and created_at>=since group by event)t),'{}'::jsonb),
 'daily',coalesce((select jsonb_agg(to_jsonb(t) order by "day") from(
 select (created_at at time zone 'Asia/Bangkok')::date as "day",count(distinct visitor_id) visitors,
 count(*) filter(where event='product_view') views,
 count(*) filter(where event='cart_add') cart,
 count(*) filter(where event='checkout_open' or event like 'manager_%') contacts
 from store_private.analytics_events where channel=p_channel and created_at>=since group by 1)t),'[]'::jsonb),
 'products',coalesce((select jsonb_agg(to_jsonb(t)) from(
 select p.id,p.brand,p.name,count(*) filter(where e.event='product_view') views,
 count(*) filter(where e.event='wishlist_add') wishlist,count(*) filter(where e.event='cart_add') cart,
 count(*) filter(where e.event='manager_product') contacts,
 count(*) filter(where e.event='manager_search_product') search_contacts
 from store_private.analytics_events e join public.products p on p.id=e.product_id where e.channel=p_channel and e.created_at>=since
 group by p.id,p.brand,p.name order by count(*) filter(where e.event='product_view') desc,p.id limit 20)t),'[]'::jsonb));
 return result;
end; $function$;

CREATE OR REPLACE FUNCTION store_private.guard_product_archive()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.available then new.archive_status:=null;
 elsif new.archive_status is null then new.archive_status:='legacy'; end if;
 if tg_op='UPDATE' and old.archive_status='sold' and new.archive_status is distinct from 'sold'
 and exists(select 1 from store_private.product_sales where product_id=old.id and voided_at is null and after_state->>'archive_status'='sold') then
  raise exception 'Для возврата проданной вещи отмените продажу в истории продаж';
 end if;
 if new.archive_status='sold' and not exists(select 1 from store_private.product_sales where product_id=new.id and voided_at is null and after_state->>'archive_status'='sold') then
  raise exception 'Отметьте продажу через форму с датой и суммой';
 end if;
 if not new.available then new.reserved:=false; end if;
 return new;
end $function$;

CREATE OR REPLACE FUNCTION store_private.record_product_sale(p_operation_id uuid, p_product_id bigint, p_revision bigint, p_sold_on date, p_amount numeric, p_variant text, p_quantity integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.products%rowtype; previous store_private.product_sales%rowtype;
 q jsonb; stock integer; remaining integer; archive text; visible boolean; before_data jsonb; after_data jsonb; label text; sale_id bigint;
begin
 perform store_private.require_workspace_admin();
 if p_operation_id is null or p_product_id is null or p_revision is null or p_sold_on is null or p_sold_on<'2000-01-01'::date or p_sold_on>(now() at time zone 'Pacific/Kiritimati')::date
 or p_amount is null or not(p_amount>=0 and p_amount<=999999999 and p_amount=trunc(p_amount))
 or p_variant is null or char_length(p_variant)>100 or p_quantity is null or p_quantity not between 1 and 9999 then
  raise exception 'Проверьте дату, целую сумму в EUR и количество';
 end if;
 select * into p from public.products where id=p_product_id for update;
 select * into previous from store_private.product_sales where operation_id=p_operation_id;
 if found then
  if previous.actor_id<>auth.uid() or previous.product_id<>p_product_id or previous.sold_on<>p_sold_on or previous.amount<>p_amount or previous.variant<>p_variant or previous.quantity<>p_quantity then raise exception 'Эта операция уже записана с другими данными'; end if;
  return jsonb_build_object('sale_id',previous.id::text,'product',case when p.id is null then null else to_jsonb(p) end,'already_recorded',true);
 end if;
 if p.id is null then raise exception 'Товар больше не существует'; end if;
 if p.revision<>p_revision then raise exception 'Карточка изменилась. Обновите список и повторите продажу'; end if;
 if p.archive_status='sold' then raise exception 'Вещь уже продана'; end if;
 before_data:=jsonb_build_object('available',p.available,'archive_status',p.archive_status,'reserved',p.reserved,'stock_quantities',p.stock_quantities);
 q:=p.stock_quantities; visible:=p.available; archive:=p.archive_status;
 if p.archive_status='legacy' then
  -- A historical confirmation must not invent or deduct a historical balance.
  visible:=false;archive:='sold';
 else
  if q is null then
   if p_quantity<>1 then raise exception 'Сначала укажите остатки по размерам в карточке'; end if;
   -- Legacy stock semantics are one item per card until explicit quantities exist.
   visible:=false;archive:='sold';
  else
   if not(q ? p_variant) then raise exception 'Размер изменился. Обновите карточку'; end if;
   stock:=(q->>p_variant)::integer;
   if p_quantity>stock then raise exception 'Недостаточно остатка выбранного размера'; end if;
   q:=jsonb_set(q,array[p_variant],to_jsonb(stock-p_quantity));
   select coalesce(sum(value::integer),0) into remaining from jsonb_each_text(q);
   if remaining=0 then visible:=false;archive:='sold'; end if;
  end if;
 end if;
 after_data:=jsonb_build_object('available',visible,'archive_status',archive,'reserved',false,'stock_quantities',q);
 select coalesce(nullif(a.display_name,''),u.email,auth.uid()::text) into label from public.store_admins a join auth.users u on u.id=a.user_id where a.user_id=auth.uid();
 insert into store_private.product_sales(operation_id,product_id,product_label,variant,quantity,amount,sold_on,actor_id,actor_label,legacy,before_state,after_state)
 values(p_operation_id,p.id,concat_ws(' ',p.brand,p.name),p_variant,p_quantity,p_amount,p_sold_on,auth.uid(),label,p.archive_status is not distinct from 'legacy',before_data,after_data) returning id into sale_id;
 update public.products set available=visible,archive_status=archive,reserved=false,stock_quantities=q where id=p.id returning * into p;
 return jsonb_build_object('sale_id',sale_id::text,'product',to_jsonb(p));
end $function$;

CREATE OR REPLACE FUNCTION public.store_record_product_sale(p_operation_id uuid, p_product_id bigint, p_revision bigint, p_sold_on date, p_amount numeric, p_variant text, p_quantity integer)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$select store_private.record_product_sale(p_operation_id,p_product_id,p_revision,p_sold_on,p_amount,p_variant,p_quantity);$function$;

CREATE OR REPLACE FUNCTION public.store_void_product_sale(p_sale_id bigint, p_revision bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$select store_private.void_product_sale(p_sale_id,p_revision,p_reason);$function$;

CREATE OR REPLACE FUNCTION store_private.void_product_sale(p_sale_id bigint, p_revision bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s store_private.product_sales%rowtype; p public.products%rowtype; label text; target bigint;
begin
 perform store_private.require_workspace_admin();
 if p_reason is null or char_length(btrim(p_reason)) not between 3 and 1000 then raise exception 'Укажите причину отмены (от 3 до 1000 символов)'; end if;
 select product_id into target from store_private.product_sales where id=p_sale_id;
 -- Same lock order as recording: product first, then ledger.
 select * into p from public.products where id=target for update;
 select * into s from store_private.product_sales where id=p_sale_id for update;
 if not found then raise exception 'Продажа не найдена'; end if;
 if s.voided_at is not null then return jsonb_build_object('product',case when p.id is null then null else to_jsonb(p) end,'already_voided',true); end if;
 if p.id is not null then
  if p_revision is null or p_revision<>p.revision then raise exception 'Карточка изменилась. Обновите список и повторите'; end if;
  if exists(select 1 from store_private.product_sales where product_id=p.id and id>s.id and voided_at is null)
  or jsonb_build_object('available',p.available,'archive_status',p.archive_status,'reserved',p.reserved,'stock_quantities',p.stock_quantities) is distinct from s.after_state then
   raise exception 'После продажи остатки или статус изменились. Сначала отмените более поздние продажи и проверьте карточку';
  end if;
 end if;
 select coalesce(nullif(a.display_name,''),u.email,auth.uid()::text) into label from public.store_admins a join auth.users u on u.id=a.user_id where a.user_id=auth.uid();
 update store_private.product_sales set voided_at=now(),voided_by=auth.uid(),voided_label=label,void_reason=btrim(p_reason) where id=s.id;
 if p.id is not null then
  update public.products set available=(s.before_state->>'available')::boolean,archive_status=s.before_state->>'archive_status',reserved=false,stock_quantities=nullif(s.before_state->'stock_quantities','null'::jsonb) where id=p.id returning * into p;
 end if;
 return jsonb_build_object('product',case when p.id is null then null else to_jsonb(p) end);
end $function$;

CREATE OR REPLACE FUNCTION store_private.product_sales_history(p_before bigint DEFAULT NULL::bigint, p_query text DEFAULT ''::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_state text DEFAULT 'active'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare rows jsonb; summary jsonb;
begin
 perform store_private.require_workspace_admin();
 if p_state is null or p_state not in ('active','voided','all') or p_query is null or char_length(p_query)>150 or (p_from is not null and p_to is not null and p_from>p_to) then raise exception 'Проверьте фильтры истории'; end if;
 with filtered as (
  select s.* from store_private.product_sales s where (p_from is null or s.sold_on>=p_from) and (p_to is null or s.sold_on<=p_to)
  and (p_state='all' or (p_state='active' and s.voided_at is null) or (p_state='voided' and s.voided_at is not null))
  and (btrim(p_query)='' or position(lower(btrim(p_query)) in lower(s.product_label))>0 or s.product_id::text=btrim(p_query))
 ), page as (
  select s.* from filtered s where p_before is null or (s.sold_on,s.id)<(select sold_on,id from store_private.product_sales where id=p_before)
  order by s.sold_on desc,s.id desc limit 31
 )
 select (select coalesce(jsonb_agg(jsonb_build_object('id',id::text,'product_id',product_id::text,'product_label',product_label,'variant',variant,'quantity',quantity,'amount',amount,'sold_on',sold_on,'recorded_at',recorded_at,'actor_label',actor_label,'legacy',legacy,'voided_at',voided_at,'voided_label',voided_label,'void_reason',void_reason) order by sold_on desc,id desc),'[]'::jsonb) from page),
 (select jsonb_build_object('count',count(*) filter(where voided_at is null),'quantity',coalesce(sum(quantity) filter(where voided_at is null),0),'amount',coalesce(sum(amount) filter(where voided_at is null),0)) from filtered)
 into rows,summary;
 return jsonb_build_object('rows',rows,'summary',summary);
end $function$;

CREATE OR REPLACE FUNCTION public.store_product_sales_history(p_before bigint DEFAULT NULL::bigint, p_query text DEFAULT ''::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_state text DEFAULT 'active'::text)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$select store_private.product_sales_history(p_before,p_query,p_from,p_to,p_state);$function$;

CREATE OR REPLACE FUNCTION store_private.upload_duty(p_day date)
 RETURNS TABLE(day date, manager_id uuid, manager_label text, target integer, is_override boolean, revision bigint, note text, active boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 with chosen as (
  select r.manager_ids[1+((p_day-r.starts_on)%cardinality(r.manager_ids))] as id,r.manager_labels
  from store_private.upload_rotations r where r.starts_on<=p_day order by r.starts_on desc limit 1
 ), resolved as (
  select case when o.day is not null then o.manager_id else c.id end as id,
   case when o.day is not null then o.manager_label else c.manager_labels->>c.id::text end as label,
   o.day is not null as overridden,coalesce(o.revision,0) as rev,coalesce(o.note,'') as memo
  from (select 1) seed left join chosen c on true left join store_private.upload_day_overrides o on o.day=p_day
 )
 select p_day,r.id,coalesce(nullif(a.display_name,''),r.label,''),case when r.id is null then 0 else 10 end,
  r.overridden,r.rev,r.memo,a.user_id is not null
 from resolved r left join public.store_admins a on a.user_id=r.id;
$function$;

CREATE OR REPLACE FUNCTION store_private.save_upload_rotation(p_starts_on date, p_manager_ids uuid[], p_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare before_row jsonb; after_row jsonb; labels jsonb; existing bigint;
begin
 perform store_private.require_workspace_admin(true);
 if p_starts_on is null or p_starts_on<(now() at time zone 'Europe/Kyiv')::date or p_starts_on>(now() at time zone 'Europe/Kyiv')::date+366 then raise exception 'Новая очередь может начинаться сегодня или в течение следующего года'; end if;
 if p_manager_ids is null or cardinality(p_manager_ids) not between 1 and 100 or array_ndims(p_manager_ids)<>1
  or array_position(p_manager_ids,null) is not null
  or cardinality(p_manager_ids)<>(select count(distinct id) from unnest(p_manager_ids) id) then raise exception 'Выберите менеджеров без повторений'; end if;
 if exists(select 1 from unnest(p_manager_ids) id where not exists(select 1 from public.store_admins a where a.user_id=id)) then raise exception 'Участник очереди должен иметь доступ к админке'; end if;
 -- Serialize same-day edits, including a first insert into an empty date.
 perform pg_advisory_xact_lock(172604,p_starts_on-date '2000-01-01');
 select revision,to_jsonb(r) into existing,before_row from store_private.upload_rotations r where starts_on=p_starts_on for update;
 if p_revision is distinct from coalesce(existing,0) then raise exception 'Очередь уже изменена. Обновите расписание и повторите.' using errcode='40001'; end if;
 select jsonb_object_agg(user_id::text,coalesce(nullif(display_name,''),'Менеджер')) into labels from public.store_admins where user_id=any(p_manager_ids);
 insert into store_private.upload_rotations(starts_on,manager_ids,manager_labels,updated_by)
 values(p_starts_on,p_manager_ids,labels,auth.uid()) on conflict(starts_on) do update set manager_ids=excluded.manager_ids,manager_labels=excluded.manager_labels,revision=store_private.upload_rotations.revision+1,updated_at=now(),updated_by=auth.uid()
 returning to_jsonb(upload_rotations) into after_row;
 insert into store_private.upload_schedule_changes(actor_id,kind,day,before_data,after_data) values(auth.uid(),'rotation',p_starts_on,before_row,after_row);
 return jsonb_build_object('saved',true);
end $function$;

CREATE OR REPLACE FUNCTION store_private.save_upload_day(p_day date, p_manager_id uuid, p_note text, p_revision bigint, p_reset boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare before_row jsonb; after_row jsonb; label text; existing bigint;
begin
 perform store_private.require_workspace_admin(true);
 if p_day is null or p_day<(now() at time zone 'Europe/Kyiv')::date or p_day>(now() at time zone 'Europe/Kyiv')::date+366 then raise exception 'Можно менять сегодняшнее и будущее дежурство в течение года'; end if;
 if p_note is null or char_length(p_note)>300 or p_reset is null then raise exception 'Примечание: до 300 символов'; end if;
 if p_manager_id is not null then
  select coalesce(nullif(display_name,''),'Менеджер') into label from public.store_admins where user_id=p_manager_id;
  if not found then raise exception 'У менеджера нет доступа к админке'; end if;
 end if;
 perform pg_advisory_xact_lock(172605,p_day-date '2000-01-01');
 select revision,to_jsonb(d) into existing,before_row from store_private.upload_day_overrides d where day=p_day for update;
 if p_revision is distinct from coalesce(existing,0) then raise exception 'Дежурство уже изменено. Обновите расписание и повторите.' using errcode='40001'; end if;
 if p_reset then delete from store_private.upload_day_overrides where day=p_day;
 else
  insert into store_private.upload_day_overrides(day,manager_id,manager_label,note,updated_by)
  values(p_day,p_manager_id,coalesce(label,''),btrim(p_note),auth.uid()) on conflict(day) do update set manager_id=excluded.manager_id,manager_label=excluded.manager_label,note=excluded.note,revision=store_private.upload_day_overrides.revision+1,updated_at=now(),updated_by=auth.uid()
  returning to_jsonb(upload_day_overrides) into after_row;
 end if;
 insert into store_private.upload_schedule_changes(actor_id,kind,day,before_data,after_data) values(auth.uid(),case when p_reset then 'reset_day' else 'day' end,p_day,before_row,after_row);
 return jsonb_build_object('saved',true);
end $function$;

CREATE OR REPLACE FUNCTION store_private.workspace_upload_items(p_day date, p_actor_id uuid DEFAULT NULL::uuid, p_before bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 perform store_private.require_workspace_admin();
 if p_day is null or p_day<date '2000-01-01' or p_day>date '2100-12-31' then raise exception 'Недопустимая дата'; end if;
 select coalesce(jsonb_agg(row_data order by id desc),'[]'::jsonb) into result from (
  select l.id,jsonb_build_object('id',l.id::text,'product_id',l.record_id,'created_at',l.changed_at,
   'actor_id',l.actor_id,'actor_label',coalesce(nullif(a.display_name,''),nullif(l.actor_label,''),case when l.actor_id is null then 'Системная загрузка' else 'Бывший сотрудник' end),
   'title',concat_ws(' ',l.after_row->>'brand',l.after_row->>'name'),'exists',p.id is not null,
   'available',p.available,'archive_status',p.archive_status) as row_data
  from store_private.store_change_log l left join public.store_admins a on a.user_id=l.actor_id
  left join public.products p on p.id=case when l.record_id~'^[0-9]{1,18}$' then l.record_id::bigint end
  where l.entity='products' and l.operation='INSERT' and l.changed_at>=p_day::timestamp at time zone 'Europe/Kyiv'
   and l.changed_at<(p_day+1)::timestamp at time zone 'Europe/Kyiv'
   and (p_actor_id is null or l.actor_id=p_actor_id) and (p_before is null or l.id<p_before)
   and not exists(select 1 from store_private.store_change_log old where old.entity='products' and old.operation='INSERT' and old.record_id=l.record_id and old.id<l.id)
  order by l.id desc limit 31
 ) rows;
 return result;
end $function$;

