CREATE TRIGGER bump_product_revision BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION bump_product_revision();

CREATE TRIGGER audit_product_changes AFTER INSERT OR DELETE OR UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION store_private.log_store_change();

CREATE TRIGGER audit_admin_changes AFTER INSERT OR DELETE OR UPDATE ON public.store_admins FOR EACH ROW EXECUTE FUNCTION store_private.log_store_change();

CREATE TRIGGER bump_admin_note_revision BEFORE UPDATE ON public.product_admin_notes FOR EACH ROW EXECUTE FUNCTION bump_product_revision();

CREATE TRIGGER audit_internal_information AFTER INSERT OR DELETE OR UPDATE ON public.product_admin_notes FOR EACH ROW EXECUTE FUNCTION store_private.log_store_change();

CREATE TRIGGER guard_product_archive BEFORE INSERT OR UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION store_private.guard_product_archive();

CREATE TRIGGER finance_entry_audit AFTER INSERT OR UPDATE ON store_private.finance_entries FOR EACH ROW EXECUTE FUNCTION store_private.audit_finance_change();

CREATE TRIGGER commission_terms_audit AFTER INSERT OR UPDATE ON store_private.commission_terms FOR EACH ROW EXECUTE FUNCTION store_private.audit_finance_change();

CREATE TRIGGER product_sale_finance AFTER INSERT OR UPDATE OF voided_at ON store_private.product_sales FOR EACH ROW EXECUTE FUNCTION store_private.sync_sale_finance();

CREATE TRIGGER product_costs_audit AFTER INSERT OR UPDATE ON store_private.product_costs FOR EACH ROW EXECUTE FUNCTION store_private.audit_finance_change();

create policy "Admins read product photo metadata" on "storage"."objects" as PERMISSIVE for SELECT to "authenticated" using (((bucket_id = 'product-photos'::text) AND (EXISTS ( SELECT 1
   FROM store_admins
  WHERE (store_admins.user_id = ( SELECT auth.uid() AS uid))))));

create policy "Admins upload product photos" on "storage"."objects" as PERMISSIVE for INSERT to "authenticated" with check (((bucket_id = 'product-photos'::text) AND ((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text) AND (EXISTS ( SELECT 1
   FROM store_admins
  WHERE (store_admins.user_id = ( SELECT auth.uid() AS uid))))));

create policy "store_mfa_photo_insert" on "storage"."objects" as RESTRICTIVE for INSERT to "authenticated" with check (((bucket_id <> 'product-photos'::text) OR ( SELECT store_private.admin_mfa_satisfied() AS admin_mfa_satisfied)));

create policy "store_mfa_photo_read" on "storage"."objects" as RESTRICTIVE for SELECT to "authenticated" using (((bucket_id <> 'product-photos'::text) OR ( SELECT store_private.admin_mfa_satisfied() AS admin_mfa_satisfied)));

create policy "Admins add products" on "public"."products" as PERMISSIVE for INSERT to "authenticated" with check ((EXISTS ( SELECT 1
   FROM store_admins
  WHERE (store_admins.user_id = ( SELECT auth.uid() AS uid)))));

create policy "Admins delete products" on "public"."products" as PERMISSIVE for DELETE to "authenticated" using ((EXISTS ( SELECT 1
   FROM store_admins
  WHERE (store_admins.user_id = ( SELECT auth.uid() AS uid)))));

create policy "Admins edit products" on "public"."products" as PERMISSIVE for UPDATE to "authenticated" using ((EXISTS ( SELECT 1
   FROM store_admins
  WHERE (store_admins.user_id = ( SELECT auth.uid() AS uid))))) with check ((EXISTS ( SELECT 1
   FROM store_admins
  WHERE (store_admins.user_id = ( SELECT auth.uid() AS uid)))));

create policy "Admins read inventory" on "public"."products" as PERMISSIVE for SELECT to "authenticated" using ((EXISTS ( SELECT 1
   FROM store_admins
  WHERE (store_admins.user_id = ( SELECT auth.uid() AS uid)))));

create policy "Catalog available products" on "public"."products" as PERMISSIVE for SELECT to "anon","authenticated" using ((available = true));

create policy "store_mfa_product_delete" on "public"."products" as RESTRICTIVE for DELETE to "authenticated" using (( SELECT store_private.admin_mfa_satisfied() AS admin_mfa_satisfied));

create policy "store_mfa_product_insert" on "public"."products" as RESTRICTIVE for INSERT to "authenticated" with check (( SELECT store_private.admin_mfa_satisfied() AS admin_mfa_satisfied));

create policy "store_mfa_product_read" on "public"."products" as RESTRICTIVE for SELECT to "authenticated" using (((available = true) OR ( SELECT store_private.admin_mfa_satisfied() AS admin_mfa_satisfied)));

create policy "store_mfa_product_update" on "public"."products" as RESTRICTIVE for UPDATE to "authenticated" using (( SELECT store_private.admin_mfa_satisfied() AS admin_mfa_satisfied)) with check (( SELECT store_private.admin_mfa_satisfied() AS admin_mfa_satisfied));

create policy "store_owner_product_delete" on "public"."products" as RESTRICTIVE for DELETE to "authenticated" using ((EXISTS ( SELECT 1
   FROM store_admins
  WHERE ((store_admins.user_id = ( SELECT auth.uid() AS uid)) AND (store_admins.access_role = 'owner'::text)))));

create policy "Admins read own membership" on "public"."store_admins" as PERMISSIVE for SELECT to "authenticated" using ((user_id = ( SELECT auth.uid() AS uid)));

create policy "store_active_membership_session" on "public"."store_admins" as RESTRICTIVE for SELECT to "authenticated" using (( SELECT store_private.admin_session_active() AS admin_session_active));

create policy "analytics_admin_read" on "store_private"."analytics_events" as PERMISSIVE for SELECT to "authenticated" using ((( SELECT store_private.admin_mfa_satisfied() AS admin_mfa_satisfied) AND (EXISTS ( SELECT 1
   FROM store_admins
  WHERE (store_admins.user_id = ( SELECT auth.uid() AS uid))))));

create policy "Store admins manage internal notes" on "public"."product_admin_notes" as PERMISSIVE for ALL to "authenticated" using (((EXISTS ( SELECT 1
   FROM store_admins
  WHERE (store_admins.user_id = ( SELECT auth.uid() AS uid)))) AND ( SELECT store_private.admin_mfa_satisfied() AS admin_mfa_satisfied))) with check (((EXISTS ( SELECT 1
   FROM store_admins
  WHERE (store_admins.user_id = ( SELECT auth.uid() AS uid)))) AND ( SELECT store_private.admin_mfa_satisfied() AS admin_mfa_satisfied)));

create policy "analytics_admin_read" on "store_private"."analytics_sessions" as PERMISSIVE for SELECT to "authenticated" using ((( SELECT store_private.admin_mfa_satisfied() AS admin_mfa_satisfied) AND (EXISTS ( SELECT 1
   FROM store_admins
  WHERE (store_admins.user_id = ( SELECT auth.uid() AS uid))))));

